tool_calls.arguments:
{"command":"cat > /tmp/gw.json <<'EOF'
{
  "apiVersion": "networking.k8s.io/v1",
  "kind": "Gateway",
  "metadata": {
    "name": "app-gateway",
    "namespace": "default"
  },
  "spec": {
    "gatewayClassName": "traefik",
    "listeners": [
      {
        "name": "http",
        "protocol": "HTTP",
        "port": 8000
      }
    ]
  }
}
EOF
kubectl apply -f /tmp/gw.json --validate=false 2>&1"}

